from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == background and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, x in comp)
            r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp)
            c1 = max(x for y, x in comp)
            rectangular = len(comp) == (r1 - r0 + 1) * (c1 - c0 + 1)
            if not rectangular:
                continue
            edge_sides = set()
            for y, x in comp:
                if y == 0: edge_sides.add('top')
                if y == h - 1: edge_sides.add('bottom')
                if x == 0: edge_sides.add('left')
                if x == w - 1: edge_sides.add('right')
            if len(edge_sides) >= 2:
                continue
            if edge_sides and (r1 == r0 or c1 == c0):
                continue
            for y, x in comp:
                out[y][x] = 4
    return out
